from pathlib import Path
from html import escape
import json,zipfile
p=Path('ArtDirection/HomeMenuArtwork-20261026')
m=json.loads((p/'Generation.json').read_text(encoding='utf-8'))
items=[{k:r[k] for k in ['id','title','file','width','height']} for r in m['images']]
thumbs=''.join(f'<button class="thumb" data-index="{i}" aria-label="View {escape(r["title"])}"><img src="{r["file"]}" alt="{escape(r["title"])}"><span><b>{i+1:02d}</b> {escape(r["title"])}</span></button>' for i,r in enumerate(items))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deadly Jenga - Home screen artwork</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0c1020;color:#f5f7ff;font:16px/1.5 system-ui,sans-serif}main{width:min(1600px,94vw);margin:28px auto 55px}header{display:flex;align-items:end;justify-content:space-between;gap:25px;flex-wrap:wrap}h1{font-size:clamp(27px,4vw,48px);line-height:1.1;margin:8px 0 14px;letter-spacing:-1px}.eyebrow{font-size:12px;letter-spacing:3px;color:#89ebdd;text-transform:uppercase}p{color:#bfc8e0;max-width:1000px}a{color:#96f5dc}button,.download{font:inherit;border:1px solid #526484;background:#192039;color:#f5f7ff;border-radius:8px;padding:10px 16px;cursor:pointer;text-decoration:none}button:hover,.download:hover{background:#344364}button:focus-visible,a:focus-visible{outline:3px solid #92f9d0;outline-offset:3px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0 12px}.toolbar label{background:#192039;border:1px solid #526484;border-radius:8px;padding:10px 14px;cursor:pointer}input{accent-color:#78edd2}.viewer{position:relative;overflow:hidden;aspect-ratio:1672/941;background:#121827;border-radius:14px;box-shadow:0 15px 65px #0006}.viewer>img{width:100%;height:100%;object-fit:contain;display:block}.overlay{position:absolute;inset:0;display:none;padding:6%;background:linear-gradient(90deg,#090c20e8 0%,#101329a6 20%,#10132930 38%,transparent 55%);pointer-events:none}.viewer.menu .overlay{display:block}.brand{font-size:clamp(25px,4.2vw,68px);line-height:.88;font-weight:1000;letter-spacing:-2px;color:white;text-shadow:0 3px 0 #4f3e97,0 7px 15px #0007}.brand em{font-style:normal;color:#9bf5dc}.fake-menu{display:grid;gap:10px;margin-top:8%;width:23%;min-width:125px}.fake-menu span{background:#211c46d9;border:1px solid #e6d9ff80;box-shadow:0 4px 15px #0003;border-radius:7px;padding:10px 14px;font-size:clamp(11px,1.3vw,20px);font-weight:800}.fake-menu span:first-child{background:#93f1d8;color:#122d37;border-color:#caffef}.overlay-note{position:absolute;left:6%;bottom:5%;font-size:clamp(8px,1vw,14px);color:#fff9}.caption{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:14px 0 24px}h2{font-size:23px;margin:0}.meta{font-size:13px;color:#a8b6d0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.thumb{padding:0;overflow:hidden;text-align:left;border:2px solid #283650;background:#172037;transition:border-color .15s,transform .15s}.thumb:hover{transform:translateY(-2px)}.thumb.active{border-color:#8cf4d4}.thumb img{width:100%;display:block;aspect-ratio:1672/941;object-fit:cover}.thumb span{display:block;padding:12px}.thumb b{color:#8cf4d4;margin-right:8px}.note{border-left:3px solid #8cf4d4;background:#19213b;padding:14px 18px;font-size:14px;margin-top:28px}.viewer:fullscreen{border-radius:0;aspect-ratio:auto;background:#000}.viewer:fullscreen>img{object-fit:contain}.viewer:fullscreen .overlay{padding:5%}footer{font-size:14px;color:#a8b6d0;margin-top:24px}@media(max-width:700px){.grid{grid-template-columns:repeat(2,1fr)}.toolbar{font-size:13px}.fake-menu{gap:5px;margin-top:6%}.fake-menu span{padding:6px 9px}.brand{letter-spacing:-1px}}@media(prefers-reduced-motion:reduce){.thumb{transition:none}}
</style></head><body><main><header><div><div class="eyebrow">Deadly Jenga / art direction</div><h1>The chaos before you press Play.</h1><p>Six gameplay-style concepts for a future home screen: collapse, survival, combat, mystery, flight and enemy chases.</p></div><a class="download" href="HomeMenuArtwork.zip" download>Download all six + prompts</a></header><div class="toolbar"><button id="prev" aria-label="Previous image">&larr; Previous</button><button id="next" aria-label="Next image">Next &rarr;</button><label><input id="menu" type="checkbox"> Preview menu layout</label><button id="full">Full screen</button><span class="meta">Arrow keys change images</span></div><section id="viewer" class="viewer" aria-label="Artwork viewer"><img id="hero" src="01-tsunami-scramble.png" alt="Tsunami Scramble"><div class="overlay"><div class="brand">DEADLY<br><em>JENGA</em></div><div class="fake-menu"><span>PLAY</span><span>CUSTOMIZE</span><span>SETTINGS</span><span>QUIT</span></div><div class="overlay-note">Menu placement concept only</div></div></section><div class="caption"><div><h2 id="title">Tsunami Scramble</h2><span id="size" class="meta">Native generated artwork</span></div><a id="original" class="download" href="01-tsunami-scramble.png" download>Download clean PNG</a></div><div class="grid">THUMBS</div><div class="note">AI-generated promotional concepts using actual game avatar/map images as visual references. These are not Unity gameplay screenshots or a promise of current in-game rendering. The menu overlay is a separate gallery layout preview; it is not baked into the PNGs. Native images are approximately 1672 &times; 941 pixels, without upscaling. No home scene or gameplay files have been changed.</div><footer><a href="Generation.json">All source references and complete generation prompts</a> &middot; Generated with built-in imagegen.</footer></main><script>
const items=ITEMS;
let index=0;
const viewer=document.getElementById('viewer'),hero=document.getElementById('hero'),original=document.getElementById('original');
function show(i){index=(i+items.length)%items.length;const item=items[index];hero.src=item.file;hero.alt=item.title;original.href=item.file;document.getElementById('title').textContent=item.title;document.getElementById('size').textContent=`${index+1} / ${items.length}  |  ${item.width} x ${item.height} native pixels  |  Clean PNG`;document.querySelectorAll('.thumb').forEach((b,n)=>{b.classList.toggle('active',n===index);b.setAttribute('aria-pressed',String(n===index));});}
document.getElementById('prev').addEventListener('click',()=>show(index-1));document.getElementById('next').addEventListener('click',()=>show(index+1));document.querySelectorAll('.thumb').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.index))));document.getElementById('menu').addEventListener('change',e=>viewer.classList.toggle('menu',e.target.checked));document.getElementById('full').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await viewer.requestFullscreen();}catch(e){window.open(hero.src,'_blank','noopener');}});document.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement)return;if(e.key==='ArrowRight'){show(index+1);e.preventDefault();}if(e.key==='ArrowLeft'){show(index-1);e.preventDefault();}});show(0);
</script></body></html>'''
page=page.replace('THUMBS',thumbs).replace('ITEMS',json.dumps(items))
(p/'index.html').write_text(page,encoding='utf-8')
script=page.split('<script>')[1].split('</script>')[0]
(p/'gallery-check.js').write_text(script,encoding='utf-8')
with zipfile.ZipFile(p/'HomeMenuArtwork.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
 for file in [p/r['file'] for r in items]+[p/'Generation.json',p/'index.html']:
  z.write(file,file.name)
assert len(items)==6
for r in items:assert (p/r['file']).exists()
print('Saved six native PNGs, prompt manifest, organized gallery and ZIP pack.')
print('ZIP size:',round((p/'HomeMenuArtwork.zip').stat().st_size/1024/1024,1),'MiB')
